"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["55138"],{47047(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>d,frontMatter:()=>o,contentTitle:()=>r,toc:()=>c,assets:()=>l});var a=JSON.parse('{"id":"nhcx/v1/concepts/how-claims-move-on-nhcx","title":"Claim Settlement","description":"End-to-end claim journey in plain language","source":"@site/docs/nhcx/v1/concepts/how-claims-move-on-nhcx.md","sourceDirName":"nhcx/v1/concepts","slug":"/nhcx/v1","permalink":"/docs/pr-49/docs/nhcx/v1","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1790289919000,"sidebarPosition":0,"frontMatter":{"title":"Claim Settlement","sidebar_label":"Claim Settlement","slug":"/nhcx/v1","sidebar_position":0,"description":"End-to-end claim journey in plain language","sidebar_class_name":"sidebar-icon sidebar-icon--route","generated":false},"sidebar":"nhcx-v1-overview","previous":{"title":"Introduction","permalink":"/docs/pr-49/docs/nhcx/v1/concepts/"},"next":{"title":"JWE Secure Messaging","permalink":"/docs/pr-49/docs/nhcx/v1/concepts/jwe-status-and-errors"}}'),i=t(62540),s=t(43023);let o={title:"Claim Settlement",sidebar_label:"Claim Settlement",slug:"/nhcx/v1",sidebar_position:0,description:"End-to-end claim journey in plain language",sidebar_class_name:"sidebar-icon sidebar-icon--route",generated:!1},r="Claim Settlement",l={},c=[{value:"What is Health Insurance?",id:"what-is-health-insurance",level:3},{value:"What is an Insurance Claim?",id:"what-is-an-insurance-claim",level:3},{value:"Types of Health Insurance Claim",id:"types-of-health-insurance-claim",level:3},{value:"Who is a Provider?",id:"who-is-a-provider",level:3},{value:"Who is a Payer?",id:"who-is-a-payer",level:3},{value:"Claim Settlement Process",id:"claim-settlement-process",level:3},{value:"The Stages of Claim Settlement on NHCX",id:"the-stages-of-claim-settlement-on-nhcx",level:2},{value:"Intimation",id:"intimation",level:4},{value:"Policy verification by the hospital",id:"policy-verification-by-the-hospital",level:4},{value:"Beneficiary and tie-up verification by the payer",id:"beneficiary-and-tie-up-verification-by-the-payer",level:4},{value:"Treatment plan intimation",id:"treatment-plan-intimation",level:4},{value:"Preauthorisation",id:"preauthorisation",level:4},{value:"Enhancement",id:"enhancement",level:4},{value:"Discharge and document submission",id:"discharge-and-document-submission",level:4},{value:"Payer query and resolution",id:"payer-query-and-resolution",level:4},{value:"Claim adjudication",id:"claim-adjudication",level:4},{value:"Payment and reconciliation",id:"payment-and-reconciliation",level:4},{value:"End-to-End Claim Lifecycle Flow",id:"end-to-end-claim-lifecycle-flow",level:4},{value:"NHCX Platform",id:"nhcx-platform",level:2},{value:"What is NHCX?",id:"what-is-nhcx",level:3},{value:"What NHCX aims to achieve?",id:"what-nhcx-aims-to-achieve",level:3},{value:"NHCX Operating Framework",id:"nhcx-operating-framework",level:3},{value:"Benefits of using NHCX",id:"benefits-of-using-nhcx",level:3},{value:"The Asynchronous Request and Callback Pattern",id:"the-asynchronous-request-and-callback-pattern",level:3},{value:"Request",id:"request",level:4},{value:"Response",id:"response",level:4}];function h(e){let n={code:"code",h1:"h1",h2:"h2",h3:"h3",h4:"h4",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"claim-settlement",children:"Claim Settlement"})}),"\n",(0,i.jsx)(n.p,{children:"Claim settlement is the end-to-end process by which an insurer or State Health Agency (SHA) evaluates, approves, and pays a request for medical expenses raised by a policyholder or treating hospital. Three participants are involved. The Provider is the treating hospital and its HMIS. The Payer is the insurance company, SHA, or TPA that adjudicates and settles the claim."}),"\n",(0,i.jsx)(n.h3,{id:"what-is-health-insurance",children:"What is Health Insurance?"}),"\n",(0,i.jsx)(n.p,{children:"Health insurance, or an Insurance Policy, is a contract between an individual and a promisor. The promisor pledges to pay the individual's medical bills, up to a set limit, in case of any ailments. The individual is commonly known as a policyholder or beneficiary whereas the promisor can be an insurance company acting by itself or on behalf of Government or any organisation or Corporate entity. It protects one\u2019s personal savings from being drained by unexpected hospital stays, surgeries, and medicines."}),"\n",(0,i.jsx)(n.h3,{id:"what-is-an-insurance-claim",children:"What is an Insurance Claim?"}),"\n",(0,i.jsx)(n.p,{children:"A health insurance claim is a formal request, by a policyholder or by the treating hospital, asking an insurance company to pay or refund money for medical care. The insurance company may act by itself or on behalf of Government or any organisation or Corporate entity."}),"\n",(0,i.jsx)(n.h3,{id:"types-of-health-insurance-claim",children:"Types of Health Insurance Claim"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Cashless"})," - A patient who is a beneficiary of a policy can avail treatment in a hospital without paying any amount out of one\u2019s pocket. This applies when the hospital is in a \u201CPreferred Network\u201D for the Insurance Company, under an existing agreement between them. It also applies when the hospital is \u201CEmpaneled\u201D under a specific scheme governing the policy. However, the amount of expenses incurred during treatment is capped either by \u201CSum Assured\u201D under the policy or some mutually agreed upon \u201CPackage Rates\u201D earmarked for a specific medical or surgical procedure."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Reimbursement"})," - Here a patient is required to pay the bills directly to the treating hospital and later get such an amount reimbursed by Insurance Company upon submission of all relevant documents. This is a common practice if the treating hospital is not a part of \u201CPreferred Network\u201D for that Insurance Company, but this model is not considered in the current scope."]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"who-is-a-provider",children:"Who is a Provider?"}),"\n",(0,i.jsx)(n.p,{children:"A Provider is the treating hospital \u201Cproviding\u201D the healthcare services to a patient, who is a beneficiary under a policy. And the HMIS software that the Provider hospital is using is known as the Provider Application. In common parlance this Provider Application is called just the \u201CProvider\u201D."}),"\n",(0,i.jsx)(n.h3,{id:"who-is-a-payer",children:"Who is a Payer?"}),"\n",(0,i.jsx)(n.p,{children:"A Payer is the Insurance Company who has issued the policy and is liable to make payments for medical expenses incurred for treatment of the policyholder. In some cases independent TPAs act on behalf of an Insurance Company to settle such medical bills and thereby assume the role of a Payer. On a similar note as above the software used by a Payer is called the Payer Application or simply \u201CPayer\u201D."}),"\n",(0,i.jsx)(n.h3,{id:"claim-settlement-process",children:"Claim Settlement Process"}),"\n",(0,i.jsx)(n.p,{children:"This is a two-way communication between the Hospital and the Insurance Company, that is, between the Provider and the Payer. It concerns the policy, the treatment rendered to the policyholder patient, and finally the payment of hospital bills after proper scrutiny of all relevant documents. It starts with the treating hospital informing the Insurance Company of an imminent claim for a patient who is to be admitted for treatment. It ends with the realisation of payment from the Insurance Company for all expenses incurred while treating the patient. The entire journey of claim settlement can be broken down into the following distinct flows or use cases."}),"\n",(0,i.jsx)(n.h2,{id:"the-stages-of-claim-settlement-on-nhcx",children:"The Stages of Claim Settlement on NHCX"}),"\n",(0,i.jsx)(n.p,{children:"The traditional ten stages of claim settlement map directly onto NHCX exchanges. They run in the order below, from intimation to payment."}),"\n",(0,i.jsx)(n.h4,{id:"intimation",children:"Intimation"}),"\n",(0,i.jsx)(n.p,{children:"The hospital informs the insurance company that a patient holding one of its policies is going to be treated for the diagnosed ailments."}),"\n",(0,i.jsx)(n.h4,{id:"policy-verification-by-the-hospital",children:"Policy verification by the hospital"}),"\n",(0,i.jsx)(n.p,{children:"The hospital checks that the patient to be treated holds a valid policy from that insurance company and that the ailments to be treated are covered under the policy."}),"\n",(0,i.jsx)(n.h4,{id:"beneficiary-and-tie-up-verification-by-the-payer",children:"Beneficiary and tie-up verification by the payer"}),"\n",(0,i.jsx)(n.p,{children:"The insurance company checks that a bona fide policyholder has come for treatment and that a proper tie-up is in place with the hospital for providing such cashless treatment."}),"\n",(0,i.jsx)(n.h4,{id:"treatment-plan-intimation",children:"Treatment plan intimation"}),"\n",(0,i.jsx)(n.p,{children:"The hospital sends the insurance company an initial intimation of the treatment plan, any procedures to be carried out, and the expected length of stay needed for treatment."}),"\n",(0,i.jsx)(n.h4,{id:"preauthorisation",children:"Preauthorisation"}),"\n",(0,i.jsx)(n.p,{children:'Once satisfied with the genuineness of the case, the insurance company sends a preliminary approval, commonly known as Preauthorisation or "PreAuth". This authorises the hospital to go ahead with treatment for the policyholder patient, and the patient is then admitted.'}),"\n",(0,i.jsx)(n.h4,{id:"enhancement",children:"Enhancement"}),"\n",(0,i.jsx)(n.p,{children:'During the course of treatment, the hospital may approach the insurance company again to notify it that additional procedures may be required or that an extension of stay is needed. This is commonly known as "Enhancement".'}),"\n",(0,i.jsx)(n.h4,{id:"discharge-and-document-submission",children:"Discharge and document submission"}),"\n",(0,i.jsx)(n.p,{children:"The patient is discharged, and the hospital submits all necessary documents to the insurance company, including consultation and clinical notes, diagnostic reports, medication details, the discharge summary and all bills."}),"\n",(0,i.jsx)(n.h4,{id:"payer-query-and-resolution",children:"Payer query and resolution"}),"\n",(0,i.jsx)(n.p,{children:'At this stage, the insurance company may ask for further explanation or for documents it considers necessary to substantiate the claim and support its adjudication. Such a communication from the insurance company to the hospital is called a "Query".'}),"\n",(0,i.jsx)(n.h4,{id:"claim-adjudication",children:"Claim adjudication"}),"\n",(0,i.jsx)(n.p,{children:'The insurance company carries out the final adjudication and conveys the outcome to the hospital, stating whether the claimed amount is "Granted", "Denied" or "Partially Granted", along with the reasons.'}),"\n",(0,i.jsx)(n.h4,{id:"payment-and-reconciliation",children:"Payment and reconciliation"}),"\n",(0,i.jsx)(n.p,{children:"The insurance company pays the hospital the granted amount for the claim. It also notifies the hospital of the bank transaction details along with other details such as applicable tax or deductions."}),"\n",(0,i.jsx)(n.h4,{id:"end-to-end-claim-lifecycle-flow",children:"End-to-End Claim Lifecycle Flow"}),"\n",(0,i.jsx)(n.mermaid,{value:'flowchart TD\n\n  A[Patient Arrives at Hospital] --\x3e B[Coverage Eligibility Check]\n  B --\x3e C[Fetch Insurance Plan & Tariff Master]\n  C --\x3e D[Submit Preauthorisation Request]\n  D --\x3e Q1{Payer Adjudication}\n  Q1 -- Query Raised --\x3e D3[Answer Query with Documents] --\x3e Q1\n  Q1 -- Approved --\x3e E[Inpatient Admission & Treatment]\n  E --\x3e E2{Case Requires Extension?}\n  E2 -- Yes --\x3e F[Submit Enhancement Request] --\x3e Q1\n  E2 -- No --\x3e G[Discharge Patient & Submit Claim]\n  G --\x3e Q2{Payer Adjudication}\n  Q2 -- Query Raised --\x3e G3[Submit Additional Documents] --\x3e Q2\n  Q2 -- Decided --\x3e H[Claim Adjudication Decision]\n  H --\x3e I[Payer Issues Payment Notice with UTR]\n  I --\x3e J[Hospital Acknowledges Settlement]\n  H -. Rejected or Partial Shortfall .-> K["Task: Reprocess or Arbitration"]\n  D -. Voluntary Withdrawal .-> L["Task: Cancel Preauth"]'}),"\n",(0,i.jsx)(n.h2,{id:"nhcx-platform",children:"NHCX Platform"}),"\n",(0,i.jsx)(n.h3,{id:"what-is-nhcx",children:"What is NHCX?"}),"\n",(0,i.jsx)(n.p,{children:"The National Health Claims Exchange (NHCX) irons out the challenges depicted above. It is developed under the Ayushman Bharat Digital Mission (ABDM) by the National Health Authority (NHA), in consultation with the Insurance Regulatory and Development Authority of India (IRDAI). The idea is to introduce a platform of exchange to the Providers and Payers so that both can transfer digitised health records and other pertinent information directly in a machine readable format to its counterpart."}),"\n",(0,i.jsx)(n.h3,{id:"what-nhcx-aims-to-achieve",children:"What NHCX aims to achieve?"}),"\n",(0,i.jsx)(n.p,{children:"The primary objective of NHCX is to streamline and standardise the processing of health insurance claims across the country, ensuring absolute interoperability across diverse systems. Provider and Payer applications may operate on completely different technology stacks. Even so, one system can seamlessly remit health information to the other in a comprehensive, digitised, machine readable format, with the very exact interpretation at both ends. It is achieved by leveraging the Fast Healthcare Interoperability Resources (FHIR) standard protocols and using international coding practices, wiping out even the slightest ambiguity in the understanding."}),"\n",(0,i.jsx)(n.h3,{id:"nhcx-operating-framework",children:"NHCX Operating Framework"}),"\n",(0,i.jsx)(n.p,{children:"On securities exchanges like NSE & BSE, anyone can buy or sell independently by merely getting connected to the platform. In the same way, the entire idea of NHCX is to connect Providers and Payers on either side. Once Providers and Payers become compliant to the NHCX protocols like using prescribed FHIR bundles and implementing universally accepted coding practices they can independently connect to one another using NHCX as a medium of exchange. The protocols and standards ensure that a health information does not lose any of its essence during the transfer."}),"\n",(0,i.jsx)(n.h3,{id:"benefits-of-using-nhcx",children:"Benefits of using NHCX"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"It is imperative that in the present day context almost every healthcare provider or hospital is generating digitised health records. But there is no point if the hospital has to convert that data into a \u201Cpdf\u201D or a \u201Cjpg\u201D file and transmit the same to the insurance company in a human readable format. NHCX is the only solution to this widespread problem"}),"\n",(0,i.jsx)(n.li,{children:"Let us consider a diagnostic report of a patient like \u201CLipid Profile\u201D that has some 10 parameter values, all very important to understand the criticality of the case. It would be very helpful for the insurance company to have those 10 different values for the individual parameters of Lipid Profile in adjudication of the case. Using NHCX such values for each of these parameters under Lipid Profile can be passed on from Provider to Payer"}),"\n",(0,i.jsx)(n.li,{children:"Since any standard hospital HMIS already captures data pertaining to a patient like medical history, allergies, medication, line of treatment, etc. it would be apt to convey those same details to the insurance company instead of taking a printout and scanning them again for email attachments or uploads, thereby ensuring chastity of data"}),"\n",(0,i.jsx)(n.li,{children:"Data precision is also safeguarded as the intervention of data entry operators is only limited to the first level entry into HMIS, rendering this to be the only source of truth. Eventually this translates to lesser queries and rejection of claims on flimsy grounds"}),"\n",(0,i.jsx)(n.li,{children:"NHCX enables maximum data transfer in the digitised format, thus allowing a Payer run AI tools and conduct automated adjudication to the maximum possible extent"}),"\n",(0,i.jsx)(n.li,{children:"Government social security schemes like Ayushman Bharat are gaining momentum, and IRDAI is advocating \u201CCashless Everywhere\u201D. More and more healthcare providers are entering the arena, and only a universal model like NHCX can support this extent of scalability"}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"the-asynchronous-request-and-callback-pattern",children:"The Asynchronous Request and Callback Pattern"}),"\n",(0,i.jsx)(n.p,{children:"Claim decisions can't be made instantly. A pre-authorisation review may take minutes to hours, and a complex claim review may take days. So NHCX handles every major action in two separate steps."}),"\n",(0,i.jsx)(n.h4,{id:"request",children:"Request"}),"\n",(0,i.jsxs)(n.p,{children:["The sender calls an action endpoint, such as ",(0,i.jsx)(n.code,{children:"preauth/submit"}),". NHCX checks the message headers, confirms who sent it, and immediately replies with an HTTP 202 Accepted receipt. This receipt only confirms that the message was received. It is not a decision on the case."]}),"\n",(0,i.jsx)(n.h4,{id:"response",children:"Response"}),"\n",(0,i.jsxs)(n.p,{children:["The receiver opens the message, makes its decision, and sends the result later to the matching callback endpoint, such as ",(0,i.jsx)(n.code,{children:"preauth/on_submit"}),". NHCX forwards this response to the sender's registered webhook, which replies with its own HTTP 202 receipt."]}),"\n",(0,i.jsx)(n.mermaid,{value:"sequenceDiagram\n  box Provider side\n    participant P as Hospital (Provider)\n  end\n  box Exchange\n    participant X as NHCX Gateway\n  end\n  box Payer side\n    participant Y as Insurer / SHA (Payer)\n  end\n  P->>X: POST preauth/submit\n  X--\x3e>P: 202 Accepted (Receipt: queued & routed)\n  X->>Y: Delivers encrypted payload\n  Y--\x3e>X: 202 Accepted\n  Note over Y: Clinical & financial adjudication\n  Y->>X: POST preauth/on_submit (Decision)\n  X--\x3e>Y: 202 Accepted\n  X->>P: Delivers decision to Provider callback\n  P--\x3e>X: 202 Accepted"})]})}function d(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}}}]);